const input=document.getElementById("json-input"),output=document.getElementById("json-output");function formatJSON(){try{const t=input.value.trim();if(!t)return output.textContent=i18n.t("common.enter_json");const e=JSON.parse(t),n=document.getElementById("sort-keys").checked?sortObject(e):e,o=document.getElementById("compact").checked?2:4;output.textContent=JSON.stringify(n,null,o),output.style.color="var(--text)"}catch(t){output.textContent="\u274C \uC624\uB958: "+t.message,output.style.color="#ef4444"}}function minifyJSON(){try{const t=input.value.trim();if(!t)return output.textContent=i18n.t("common.enter_json");const e=JSON.parse(t);output.textContent=JSON.stringify(e),output.style.color="var(--text)"}catch(t){output.textContent="\u274C \uC624\uB958: "+t.message,output.style.color="#ef4444"}}function sortObject(t){return Array.isArray(t)?t.map(sortObject):t!==null&&typeof t=="object"?Object.keys(t).sort().reduce((e,n)=>(e[n]=sortObject(t[n]),e),{}):t}function copyResult(){copyToClipboard(output.textContent).then(()=>showToast(i18n.t("common.copied")))}function downloadResult(){const t=output.textContent;if(!t||t===i18n.t("common.result_placeholder")||t.startsWith("\u274C"))return showToast(i18n.t("common.no_result"));downloadFile(t,"formatted.json")}function clearAll(){input.value="",output.textContent=i18n.t("common.result_placeholder"),output.style.color="var(--text-muted)"}
